const listInvoices = `-- name: ListInvoices :many
SELECT 
    i.id, i.invoice_no, i.job_card_id, i.customer_id, i.vehicle_id, i.cash_session_id, i.status, i.subtotal, i.discount_total, i.tax_bps, i.tax_total, i.total, i.paid_total, i.balance, i.issued_at, i.due_at, i.paid_at, i.voided_at, i.void_reason, i.voided_by, i.notes, i.created_by, i.created_at, i.updated_at,
    c.name AS customer_name,
    c.phone AS customer_phone,
    v.plate_no,
    jc.job_no
FROM invoices i
JOIN customers c ON c.id = i.customer_id
LEFT JOIN vehicles v ON v.id = i.vehicle_id
LEFT JOIN job_cards jc ON jc.id = i.job_card_id
WHERE 
    ($1::TEXT IS NULL OR $1::TEXT = '' OR i.status = $1)
    AND (
        $2::TEXT IS NULL 
        OR $2::TEXT = ''
        OR i.invoice_no ILIKE '%' || $2 || '%'
        OR c.name ILIKE '%' || $2 || '%'
        OR c.phone ILIKE '%' || $2 || '%'
        OR v.plate_no ILIKE '%' || $2 || '%'
    )
ORDER BY i.created_at DESC
LIMIT $3 OFFSET $4
`

type ListInvoicesParams struct {
	Column1 string `json:"column_1"`
	Column2 string `json:"column_2"`
	Limit   int32  `json:"limit"`
	Offset  int32  `json:"offset"`
}

